import 'package:dio/dio.dart';
import 'package:stash/stash_api.dart';
import 'package:stash_dio/stash_dio.dart';
import 'package:stash_memory/stash_memory.dart';

void main() async {
  final store = await newMemoryCacheStore();
  final cache = store.cache(eventListenerMode: EventListenerMode.synchronous);
  final dio = Dio(BaseOptions(baseUrl: 'https://jsonplaceholder.typicode.com'))
    ..interceptors.addAll([
      cache.interceptor('/todos/1'),
      LogInterceptor(requestHeader: false, requestBody: false, responseHeader: false, responseBody: false)
    ]);
  final task = await dio.get('/todos/1').then((r) => r.data);
  print(task);
}
